import { mkdirSync, mkdtempSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import { selectSourceFiles } from './source-files.mjs';

const ONE_FUNCTION = 'export const value = () => 1;\n';

const PROJECT = {
  'src/ok/a.ts': ONE_FUNCTION,
  'src/ok/b.tsx': ONE_FUNCTION,
  'src/ok/c.mjs': ONE_FUNCTION,
  'src/ok/d.d.ts': ONE_FUNCTION,
  'src/ok/e.test.ts': ONE_FUNCTION,
  'src/ok/f.skip.ts': ONE_FUNCTION,
  'src/ok/g.ts': `/* eslint-disable */\n// @generated by a tool\n${ONE_FUNCTION}`,
  'src/ok/h.ts': `#!/usr/bin/env node\n// header\n/* DO NOT EDIT\n*/\n${ONE_FUNCTION}`,
  'src/ok/i.ts': `\uFEFF// Do not edit\n${ONE_FUNCTION}`,
  'src/ok/j.ts': `${ONE_FUNCTION}// DO NOT EDIT later\n`,
  'src/ok/k.ts': `/* unterminated @generated ${ONE_FUNCTION}`,
  'src/x.generated.ts': ONE_FUNCTION,
  'src/gen/l.ts': ONE_FUNCTION,
  'src/generated/m.ts': ONE_FUNCTION,
  'src/legacy/n.ts': ONE_FUNCTION,
  'src/__tests__/o.ts': ONE_FUNCTION,
  'src/dist/p.ts': ONE_FUNCTION,
  'build/src/q.ts': ONE_FUNCTION,
  'src/ok/r.mts': ONE_FUNCTION,
};

let root;

beforeAll(() => {
  root = mkdtempSync(path.join(tmpdir(), 'nitpicker-crap-files-'));
  for (const [name, text] of Object.entries(PROJECT)) {
    mkdirSync(path.dirname(path.join(root, name)), { recursive: true });
    writeFileSync(path.join(root, name), text);
  }
});

afterAll(() => {
  rmSync(root, { recursive: true, force: true });
});

function select(extensions, excludes) {
  const { files, audit } = selectSourceFiles(
    root,
    Object.keys(PROJECT).map((name) => path.join(root, name)),
    { extensions, excludes },
  );
  return { files: files.map((file) => path.relative(root, file)), audit };
}

describe('CRAP source file selection', () => {
  it('keeps TypeScript sources and drops tests, declarations, build output and generated code', () => {
    const { files, audit } = select(['ts', 'tsx', 'mts', 'cts'], ['src/legacy/**', '*.skip.ts']);

    expect(files).toEqual(['src/ok/a.ts', 'src/ok/b.tsx', 'src/ok/j.ts', 'src/ok/r.mts']);
    expect(audit).toEqual({
      candidateFiles: 13,
      includedFiles: 4,
      excludedFiles: 9,
      reasons: [
        { source: 'default', kind: 'generatedMarker', rule: '@generated', count: 2 },
        { source: 'default', kind: 'generatedMarker', rule: 'Do not edit', count: 1 },
        { source: 'default', kind: 'generatedMarker', rule: 'DO NOT EDIT', count: 1 },
        { source: 'default', kind: 'path', rule: '**/*.generated.ts', count: 1 },
        { source: 'default', kind: 'path', rule: 'directory segment contains generated', count: 1 },
        { source: 'default', kind: 'path', rule: 'directory segment is gen', count: 1 },
        { source: 'user', kind: 'path', rule: '*.skip.ts', count: 1 },
        { source: 'user', kind: 'path', rule: 'src/legacy/**', count: 1 },
      ],
    });
  });

  it('adds JavaScript files for a JavaScript project', () => {
    const { files } = select(
      ['ts', 'mts', 'cts', 'js', 'mjs', 'cjs'],
      ['src/legacy/**', '*.skip.ts'],
    );

    expect(files).toEqual(['src/ok/a.ts', 'src/ok/c.mjs', 'src/ok/j.ts', 'src/ok/r.mts']);
  });
});
